"use client";import{createClient}from"@/lib/supabase/client";import{useRouter}from"next/navigation";export default function VendorClient({vendor,orders}:{vendor:any,orders:any[]}){const s=createClient(),r=useRouter();async function online(){await s.from("vendor_profiles").update({is_available:!vendor.is_available}).eq("user_id",vendor.user_id);r.refresh()}async function respond(id:number,yes:boolean){const{error}=await s.rpc("vendor_respond_offer",{p_order_id:id,p_accept:yes});if(error)return alert(error.message);if(!yes)await s.rpc("assign_nearest_vendor",{p_order_id:id});r.refresh()}async function status(id:number,x:string){const{error}=await s.rpc("vendor_set_order_status",{p_order_id:id,p_status:x});if(error)return alert(error.message);r.refresh()}return <><section className="card"><div className="row"><div><b>{vendor.business_name}</b><p className="muted">{vendor.status} · Loyalty code {vendor.loyalty_code||"—"}</p></div><span className="badge">{vendor.is_available?"Online":"Offline"}</span></div><button className="btn alt" onClick={online}>{vendor.is_available?"Go offline":"Go online"}</button></section><h2>Orders</h2>{orders.length===0&&<section className="card">No active orders.</section>}{orders.map(o=><section className="card" key={o.id}><div className="row"><b>{o.order_code}</b><span className="badge">{String(o.status).replaceAll("_"," ")}</span></div><p><b>{o.quantity_kg} kg</b> · ₦{(Number(o.gas_amount_kobo)/100).toLocaleString()}</p><p>{o.delivery_address}</p>{o.recipient_name&&<p>Recipient: {o.recipient_name} · {o.recipient_phone}</p>}{o.status==="offered"&&<div className="twocol"><button className="btn" onClick={()=>respond(o.id,true)}>Accept</button><button className="btn danger" onClick={()=>respond(o.id,false)}>Decline</button></div>}{o.status==="accepted"&&<button className="btn" onClick={()=>status(o.id,"preparing")}>Start preparing</button>}{o.status==="preparing"&&<button className="btn" onClick={()=>status(o.id,"out_for_delivery")}>Mark out for delivery</button>}{o.status==="out_for_delivery"&&<button className="btn" onClick={()=>status(o.id,"delivered")}>Confirm delivered</button>}</section>)}</>}